"""B+ Tree container supporting insert, search, and range query."""

from typing import Any, List, Optional
from internal_node import InternalNode
from leaf_node import LeafNode


class BPlusTree:
    def __init__(self, max_keys: int = 3):
        self.max_keys = max_keys
        self.root: LeafNode | InternalNode = LeafNode(max_keys)

    def insert(self, key: int, value: Any) -> None:
        if self.root.is_leaf:
            assert isinstance(self.root, LeafNode)
            split_res = self.root.insert(key, value)
            if split_res:
                promoted_key, right_leaf = split_res
                new_root = InternalNode(self.max_keys)
                new_root.keys = [promoted_key]
                new_root.children = [self.root, right_leaf]
                self.root = new_root
        else:
            assert isinstance(self.root, InternalNode)
            # Simple 2-level insertion
            idx = 0
            while idx < len(self.root.keys) and key >= self.root.keys[idx]:
                idx += 1
            child = self.root.children[idx]
            assert isinstance(child, LeafNode)
            split_res = child.insert(key, value)
            if split_res:
                promoted_key, right_leaf = split_res
                self.root.keys.insert(idx, promoted_key)
                self.root.children.insert(idx + 1, right_leaf)

    def search(self, key: int) -> Optional[Any]:
        curr = self.root
        while not curr.is_leaf:
            assert isinstance(curr, InternalNode)
            idx = 0
            while idx < len(curr.keys) and key >= curr.keys[idx]:
                idx += 1
            curr = curr.children[idx]
        assert isinstance(curr, LeafNode)
        for k, v in zip(curr.keys, curr.values):
            if k == key:
                return v
        return None

    def range_query(self, min_key: int, max_key: int) -> List[Any]:
        curr = self.root
        while not curr.is_leaf:
            assert isinstance(curr, InternalNode)
            idx = 0
            while idx < len(curr.keys) and min_key >= curr.keys[idx]:
                idx += 1
            curr = curr.children[idx]
        assert isinstance(curr, LeafNode)
        results = []
        leaf: Optional[LeafNode] = curr
        while leaf:
            for k, v in zip(leaf.keys, leaf.values):
                if min_key <= k <= max_key:
                    results.append(v)
                elif k > max_key:
                    return results
            leaf = leaf.next_leaf
        return results
